_recent_by_group = {}

def choose_question(group_id=None, category=None):
    pool = [q for q in QUESTIONS if category is None or q[0] == category]
    if not pool:
        pool = QUESTIONS
    recent = _recent_by_group.setdefault(str(group_id), []) if group_id is not None else []
    available = [q for q in pool if q[1] not in recent]
    if not available:
        available = pool
    chosen = random.choice(available)
    if group_id is not None:
        recent.append(chosen[1])
        del recent[:-100]
    return chosen
